import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("history follows", () => {
  test("history follows", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.loadSheet(pg_uma, `${sheet}-t`);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    await ui.loadSheet(pg_uma, sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.editPerson(pg_uma, p_ada, {"grade": "B"})).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.transfer(pg_vic, p_ada, `${sheet}-t`)).toBe(true);
    await ui.expectAuditView(pg_vic, "Ada", [
      `PERSON_TRANSFERRED sheet=${sheet} by=vic name=Ada to=${sheet}-t`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=10.00 due-total=n/a overdue-total=0.00`,
      `PERSON_EDITED sheet=${sheet} by=uma name=Ada grade=B`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=10.00 due-total=1.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-10 number=1`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-10`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`
    ]);
    await ui.loadSheet(pg_vic, `${sheet}-t`);
    const p_ada_2 = await ui.personId(pg_vic, "Ada");
    const c_ada_0_2 = await ui.claimAt(pg_vic, p_ada_2, 0);
    await ui.refresh(pg_vic);
    await expect(pg_vic.getByTestId("person-row-" + p_ada_2).getByTestId("person-name")).toHaveText("Ada");
    await expect(pg_vic.getByTestId("person-row-" + p_ada_2).getByTestId("person-origin")).toHaveText(`${sheet}`);
    await expect(pg_vic.getByTestId("person-row-" + p_ada_2).getByTestId("person-grade")).toHaveText("B");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_0_2).getByTestId("claim-status")).toHaveText("OPEN");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_0_2).getByTestId("claim-due")).toHaveText("n/a");
    const c_ada_1 = ui.must(await ui.addClaim(pg_vic, p_ada_2, {"amount": "5.00"}));
    expect(await ui.claimAction(pg_vic, c_ada_1, "open")).toBe(true);
    await ui.expectAuditView(pg_vic, "ada", [
      `ROLLUP sheet=${sheet}-t by=vic person=Ada claimed=15.00 due-total=n/a overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet}-t by=vic person=Ada amount=5.00 date=2026-03-10 number=2`,
      `CLAIM_ADDED sheet=${sheet}-t by=vic person=Ada amount=5.00 date=2026-03-10`,
      `ROLLUP sheet=${sheet}-t by=vic person=Ada claimed=10.00 due-total=n/a overdue-total=0.00`,
      `PERSON_TRANSFERRED sheet=${sheet}-t by=vic name=Ada from=${sheet}`,
      `PERSON_TRANSFERRED sheet=${sheet} by=vic name=Ada to=${sheet}-t`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=10.00 due-total=n/a overdue-total=0.00`,
      `PERSON_EDITED sheet=${sheet} by=uma name=Ada grade=B`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=10.00 due-total=1.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-10 number=1`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-10`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`
    ]);
    await ui.expectAuditView(pg_vic, "", [
      `TOTALS sheet=${sheet}-t by=vic claimed-total=15.00 due-total=0.00 overdue-total=0.00`,
      `ROLLUP sheet=${sheet}-t by=vic person=Ada claimed=15.00 due-total=n/a overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet}-t by=vic person=Ada amount=5.00 date=2026-03-10 number=2`,
      `CLAIM_ADDED sheet=${sheet}-t by=vic person=Ada amount=5.00 date=2026-03-10`,
      `TOTALS sheet=${sheet}-t by=vic claimed-total=10.00 due-total=0.00 overdue-total=0.00`,
      `ROLLUP sheet=${sheet}-t by=vic person=Ada claimed=10.00 due-total=n/a overdue-total=0.00`,
      `PERSON_TRANSFERRED sheet=${sheet}-t by=vic name=Ada from=${sheet}`,
      `RATE_SET sheet=${sheet}-t by=uma grade=A rate=20.00`
    ]);
    await ui.refresh(pg_vic);
    await expect(pg_vic.getByTestId("person-row-" + p_ada_2).getByTestId("person-origin")).toHaveText(`${sheet}`);
    await ui.expectAudit(`${sheet}-t`, [
      `RATE_SET sheet=${sheet}-t by=uma grade=A rate=20.00`,
      `PERSON_TRANSFERRED sheet=${sheet}-t by=vic name=Ada from=${sheet}`,
      `ROLLUP sheet=${sheet}-t by=vic person=Ada claimed=10.00 due-total=n/a overdue-total=0.00`,
      `TOTALS sheet=${sheet}-t by=vic claimed-total=10.00 due-total=0.00 overdue-total=0.00`,
      `CLAIM_ADDED sheet=${sheet}-t by=vic person=Ada amount=5.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet}-t by=vic person=Ada amount=5.00 date=2026-03-10 number=2`,
      `ROLLUP sheet=${sheet}-t by=vic person=Ada claimed=15.00 due-total=n/a overdue-total=0.00`,
      `TOTALS sheet=${sheet}-t by=vic claimed-total=15.00 due-total=0.00 overdue-total=0.00`
    ]);
  });
  test("history follows scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-20");
    await ui.setSetting(pg_uma, "clerk-limit", "1.50");
    await ui.setSetting(pg_uma, "terms", "10");
    await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
    await ui.setSetting(pg_uma, "cap", "2.00");
    await ui.setSetting(pg_uma, "perm-void", "clerk");
    expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
    await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
    await ui.setSetting(pg_uma, "proof-threshold-C", "4.00");
    expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
    expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
    await ui.loadSheet(pg_uma, `${sheet}-p`);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    await ui.loadSheet(pg_uma, sheet);
    await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
    await ui.setSetting(pg_uma, "pot", "7.77");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00", "from": "2026-03-01", "to": "2026-03-12"})).toBe(true);
    expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"})).toBeNull();
    expect(await ui.editPerson(pg_uma, p_ada, {"grade": "B"})).toBe(true);
    const c_dot_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Dot", "amount": "7.77"}));
    const p_dot = await ui.personId(pg_uma, "Dot");
    await ui.setSetting(pg_uma, "cap", "");
    expect(await ui.periodAction(pg_uma, "2026-04", "soft-close")).toBe(true);
    expect(await ui.movePerson(pg_uma, p_dot, "up")).toBe(true);
    expect(await ui.ratePreview(pg_uma, "B", "7.50")).toEqual({ count: 0, diff: "0.00" });
    expect(await ui.claimAction(pg_uma, c_dot_0, "open")).toBe(true);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_dot).getByTestId("person-claimed")).toHaveText("7.77");

