        rollup.recordSince(sheetId, user, beforeHere);
        audit.change("PERSON_TRANSFERRED", toSheetId, user, "name=" + arrived.getName(), "from=" + sheetId);
        rollup.recordSince(toSheetId, user, beforeThere);
        return arrived;
    }

